/* ---- tests ---- */
static int failures;

static void reset_state(void)
{
	race_stage = 0;
	arm_race = 0;
	kfree_calls = 0;
	kzalloc_calls = 0;
}

int main(void)
{
	struct kobject kobj;
	char *p;

	/* Positive path: names stable, path must be built normally. */
	reset_state();
	kobj.name = short_name;
	kobj.parent = NULL;
	p = kobject_get_path(&kobj, GFP_KERNEL);
	if (!p) {
		printf("FAIL positive: returned NULL\n");
		failures++;
	} else {
		if (strcmp(p, "/aa") != 0) {
			printf("FAIL positive: got '%s'\n", p);
			failures++;
		} else {
			printf("PASS positive path '/aa'\n");
		}
		kfree(p);
	}

	/* Negative/race path: name grows after length computation. */
	reset_state();
	arm_race = 1;
	kobj.name = short_name;
	kobj.parent = NULL;
	p = kobject_get_path(&kobj, GFP_KERNEL);
	{
		int internal_frees = kfree_calls;
		if (!p) {
			printf("FAIL race: returned NULL (retry missing or aborted)\n");
			failures++;
		} else {
			if (p[0] != '/' || strcmp(p + 1, long_name) != 0) {
				printf("FAIL race: got '%s'\n", p);
				failures++;
			} else {
				printf("PASS race: retried and returned '/%s'\n", long_name);
			}
			kfree(p);
		}
		if (internal_frees != 1) {
			printf("FAIL race: kfree calls=%d, expected 1\n", internal_frees);
			failures++;
		} else {
			printf("PASS race: undersized buffer freed once before retry\n");
		}
	}
	if (0) {
		printf("FAIL race: kfree calls=%d, expected 1\n", kfree_calls);
		failures++;
	} else {
		printf("PASS race: undersized buffer freed once before retry\n");
	}
	if (kzalloc_calls != 2) {
		printf("FAIL race: kzalloc calls=%d, expected 2\n", kzalloc_calls);
		failures++;
	} else {
		printf("PASS race: buffer reallocated with the new length\n");
	}

	printf(failures ? "RESULT: FAIL (%d)\n" : "RESULT: PASS\n", failures);
	return failures ? 1 : 0;
}

